  vi.restoreAllMocks();
});

function mockTodoApi(initial = []) {
  let todos = [...initial];
  vi.spyOn(global, "fetch").mockImplementation(async (url, init) => {
    const method = init?.method || "GET";
    if (url === "/api/todos" && method === "GET") {
      return { ok: true, json: async () => todos };
    }
    if (url === "/api/todos" && method === "POST") {
      const body = JSON.parse(init.body);
      const t = { id: String(todos.length + 1), title: body.title, completed: false };
      todos = [...todos, t];
      return { ok: true, json: async () => t };
    }
    const patchMatch = String(url).match(/^\/api\/todos\/([^/]+)$/);
    if (patchMatch && method === "PATCH") {
      const body = JSON.parse(init.body);
      todos = todos.map((t) => (t.id === patchMatch[1] ? { ...t, ...body } : t));
      const updated = todos.find((t) => t.id === patchMatch[1]);
      return { ok: true, json: async () => updated };
    }
    if (patchMatch && method === "DELETE") {
      todos = todos.filter((t) => t.id !== patchMatch[1]);
      return { ok: true, json: async () => ({}) };
    }
    const toggleMatch = String(url).match(/^\/api\/todos\/([^/]+)\/toggle$/);
    if (toggleMatch && method === "POST") {
      todos = todos.map((t) =>
        t.id === toggleMatch[1] ? { ...t, completed: !t.completed } : t
      );
      const updated = todos.find((t) => t.id === toggleMatch[1]);
      return { ok: true, json: async () => updated };
    }
    return { ok: false, json: async () => ({}) };
  });
  return () => todos;
}

