  it("loads and adds a todo via API", async () => {
    const user = userEvent.setup();
    mockTodoApi([]);
    render(<App />);
    await waitFor(() => expect(screen.getByText("No todos yet.")).toBeInTheDocument());
    await user.type(screen.getByPlaceholderText("New todo"), "Buy milk");
    await user.click(screen.getByRole("button", { name: "Add" }));
    await waitFor(() => expect(screen.getByText("Buy milk")).toBeInTheDocument());
  });

  it("toggles and deletes a todo via API", async () => {
    const user = userEvent.setup();
    mockTodoApi([{ id: "1", title: "Ship", completed: false }]);
    render(<App />);
    await waitFor(() => expect(screen.getByText("Ship")).toBeInTheDocument());
    await user.click(screen.getByRole("button", { name: "Toggle" }));
    await waitFor(() => {
      expect(screen.getByText("Ship").closest("li")).toHaveClass("done");
    });
    await user.click(screen.getByRole("button", { name: "Delete" }));
